package com.wiseway.service;
import java.util.*; import org.springframework.stereotype.Service;
@Service public class GeocodingService { private final LocationService catalog; private final Optional<GeocodingProvider> external; private final OsmTransitRoutingProvider transit; public GeocodingService(LocationService c,Optional<GeocodingProvider> e,OsmTransitRoutingProvider t){catalog=c;external=e;transit=t;} public List<LocationService.Location> search(String q){var catalogResults=catalog.search(q);var photonResults=external.map(x->x.search(q)).orElseGet(List::of);var stops=transit.searchStops(q);return java.util.stream.Stream.of(stops.stream(),catalogResults.stream(),photonResults.stream()).flatMap(x->x).distinct().limit(12).toList();} }
